"""Replicated growable array (RGA) CRDT for an editable string sequence.

Every local ``insert(index, value)`` mints a unique node id
``(sequence, replica_id)`` from a Lamport-style counter: the counter starts at
zero, is advanced to the greatest sequence observed via every merge, and is
incremented once per insert. Nodes hang off their predecessor (the visible
element immediately to the left at insert time, or the implicit head root).
When several inserts share a predecessor they are siblings and are ordered by
their id in *descending* order — greater sequence first, with the Unicode code
point order of ``replica_id`` breaking ties — and each sibling's own branch is
emitted before the next sibling. Because a freshly minted id is greater than
every id already known on this replica, an insert always lands exactly at the
requested zero-based visible position.

``delete`` is an observed remove: it tombstones only elements currently
visible on this replica. The node keeps its identity in the tombstone set, so
redelivery never errors or resurrects it; concurrent inserts never observed by
the remover are unaffected and a later insert at the same slot is never
swallowed by the old tombstone. The node map, predecessor links and tombstone
set only grow; merging unions them, which makes delivery idempotent,
commutative and associative.
"""

from __future__ import annotations

NodeId = tuple[int, str]

# Sentinel predecessor for nodes inserted at index 0 (the implicit head root).
ROOT: NodeId | None = None


def _validate_replica_id(replica_id: object) -> str:
    if not isinstance(replica_id, str):
        raise TypeError("replica_id must be a non-empty string")
    if replica_id == "":
        raise ValueError("replica_id must be a non-empty string")
    return replica_id


def _validate_index(index: object) -> int:
    if not isinstance(index, int) or isinstance(index, bool):
        raise TypeError("index must be an integer")
    return index


def _parse_node_id(raw_id: object) -> NodeId:
    """Parse a JSON-shape ``[sequence, origin_id]`` node id into a tuple."""
    if not isinstance(raw_id, list) or len(raw_id) != 2:
        raise ValueError("node ids must be [sequence, origin_id] lists")
    sequence, origin = raw_id
    if not isinstance(sequence, int) or isinstance(sequence, bool):
        raise ValueError("node id sequence must be an integer")
    if sequence < 1:
        raise ValueError("node id sequence must be greater than zero")
    if not isinstance(origin, str) or origin == "":
        raise ValueError("node id origin must be a non-empty string")
    return sequence, origin


class RGA:
    """A replicated editable string sequence identified by a ``replica_id``."""

    def __init__(self, replica_id: str) -> None:
        self._replica_id = _validate_replica_id(replica_id)
        # Lamport-style greatest sequence known on this replica. Local
        # inserts use counter + 1, so a new id always dominates every id that
        # was visible when the insertion position was chosen.
        self._counter = 0
        # node id -> (stored string, predecessor id or None for the root).
        self._nodes: dict[NodeId, tuple[str, NodeId | None]] = {}
        self._tombstones: set[NodeId] = set()

    @property
    def replica_id(self) -> str:
        return self._replica_id

    def _visible_nodes(self) -> list[NodeId]:
        """Return all live node ids in RGA order (the tree weave)."""
        children: dict[NodeId | None, list[NodeId]] = {}
        for node_id, (_value, predecessor) in self._nodes.items():
            children.setdefault(predecessor, []).append(node_id)
        for siblings in children.values():
            # Descending id order: greater sequence first, then the greater
            # replica id in Unicode order. Tuple ordering is exactly that.
            siblings.sort(reverse=True)

        ordered: list[NodeId] = []
        # Stack holds nodes deepest-next first: siblings are pushed in
        # reverse sorted order so pop() takes the greatest id. The root
        # children follow the same rule as nested children.
        stack: list[NodeId] = list(reversed(children.get(ROOT, ())))
        while stack:
            node_id = stack.pop()
            ordered.append(node_id)
            # The depth-first walk keeps each sibling's branch contiguous.
            stack.extend(reversed(children.get(node_id, ())))
        return [
            node_id for node_id in ordered if node_id not in self._tombstones
        ]

    def values(self) -> list[str]:
        """Return a fresh list of the visible strings in sequence order."""
        return [self._nodes[node_id][0] for node_id in self._visible_nodes()]

    def insert(self, index: int, value: str) -> None:
        """Insert ``value`` at the visible zero-based ``index``.

        ``index`` may equal the current length to append. The new node gets a
        unique id minted from the local counter and this replica's id.
        Raises ``TypeError`` for a non-integer index (booleans included) or a
        non-string value, ``IndexError`` when the index is out of range; a
        failed call leaves the state unchanged.
        """
        index = _validate_index(index)
        if not isinstance(value, str):
            raise TypeError("value must be a string")
        visible = self._visible_nodes()
        if index < 0 or index > len(visible):
            raise IndexError("insert index out of range")
        predecessor = visible[index - 1] if index > 0 else ROOT
        self._counter += 1
        node_id = (self._counter, self._replica_id)
        self._nodes[node_id] = (value, predecessor)

    def delete(self, index: int) -> str:
        """Tombstone the visible element at ``index`` and return its string.

        Only an element currently observed on this replica can be deleted; a
        concurrent insert never seen here is unaffected. Raises ``TypeError``
        for a non-integer index (booleans included) and ``IndexError`` when the
        sequence is empty or the index is out of range; a failed call leaves
        the state unchanged.
        """
        index = _validate_index(index)
        visible = self._visible_nodes()
        if index < 0 or index >= len(visible):
            raise IndexError("delete index out of range")
        node_id = visible[index]
        value = self._nodes[node_id][0]
        self._tombstones.add(node_id)
        return value

    def merge(self, other: "RGA") -> "RGA":
        """Absorb ``other``'s state in place and return ``self``.

        Unions the node histories, predecessor links and tombstones and adopts
        the greatest observed counter; ``other`` is never modified. Repeated,
        reordered or stale merges converge to the same sequence.

        Raises ``ValueError`` — leaving both states untouched — when the very
        same node id carries a different string or a different predecessor on
        the two sides, which means two live replicas share a ``replica_id``
        and minted colliding ids.
        """
        if not isinstance(other, RGA):
            raise TypeError("can only merge with another RGA")

        # Validate every shared id before mutating anything so a conflict
        # leaves both states unchanged.
        for node_id, (value, predecessor) in other._nodes.items():
            local = self._nodes.get(node_id)
            if local is not None and local != (value, predecessor):
                raise ValueError(
                    "the same node id is bound to a different value or "
                    "predecessor"
                )

        for node_id, record in other._nodes.items():
            if node_id not in self._nodes:
                self._nodes[node_id] = record
        self._tombstones.update(other._tombstones)
        if other._counter > self._counter:
            self._counter = other._counter
        return self

    def snapshot(self) -> dict[str, object]:
        """Return a fresh JSON-serializable snapshot of this sequence."""
        nodes = [
            {
                "id": [sequence, origin],
                "value": self._nodes[(sequence, origin)][0],
                "prev": self._encode_predecessor(
                    self._nodes[(sequence, origin)][1]
                ),
            }
            for sequence, origin in sorted(self._nodes)
        ]
        tombstones = [
            [sequence, origin] for sequence, origin in sorted(self._tombstones)
        ]
        return {
            "replica_id": self._replica_id,
            "counter": self._counter,
            "nodes": nodes,
            "tombstones": tombstones,
        }

    @staticmethod
    def _encode_predecessor(predecessor: NodeId | None) -> list[object] | None:
        if predecessor is None:
            return None
        return [predecessor[0], predecessor[1]]

    @classmethod
    def from_snapshot(cls, snapshot: object) -> "RGA":
        """Restore an RGA from a :meth:`snapshot`-compatible dict."""
        if not isinstance(snapshot, dict):
            raise TypeError("snapshot must be a dict")

        if set(snapshot.keys()) != {
            "replica_id",
            "counter",
            "nodes",
            "tombstones",
        }:
            raise ValueError(
                "snapshot must contain exactly 'replica_id', 'counter', "
                "'nodes' and 'tombstones'"
            )

        replica_id = snapshot["replica_id"]
        if not isinstance(replica_id, str) or replica_id == "":
            raise ValueError("replica_id must be a non-empty string")

        counter = snapshot["counter"]
        if not isinstance(counter, int) or isinstance(counter, bool):
            raise ValueError("counter must be a non-negative integer")
        if counter < 0:
            raise ValueError("counter must be a non-negative integer")

        raw_nodes = snapshot["nodes"]
        if not isinstance(raw_nodes, list):
            raise ValueError("nodes must be a list")

        nodes: dict[NodeId, tuple[str, NodeId | None]] = {}
        for raw_node in raw_nodes:
            if not isinstance(raw_node, dict):
                raise ValueError("each node must be a dict")
            if set(raw_node.keys()) != {"id", "value", "prev"}:
                raise ValueError(
                    "each node must contain exactly 'id', 'value' and 'prev'"
                )
            node_id = _parse_node_id(raw_node["id"])
            if node_id in nodes:
                raise ValueError("duplicate node id")
            value = raw_node["value"]
            if not isinstance(value, str):
                raise ValueError("node value must be a string")
            raw_prev = raw_node["prev"]
            predecessor: NodeId | None
            if raw_prev is None:
                predecessor = None
            else:
                predecessor = _parse_node_id(raw_prev)
            nodes[node_id] = (value, predecessor)

        raw_tombstones = snapshot["tombstones"]
        if not isinstance(raw_tombstones, list):
            raise ValueError("tombstones must be a list")
        tombstones: set[NodeId] = set()
        for raw_id in raw_tombstones:
            node_id = _parse_node_id(raw_id)
            if node_id in tombstones:
                raise ValueError("duplicate tombstone entry")
            tombstones.add(node_id)

        # Structural validity, first pass: every predecessor must exist.
        for _node_id, (_value, predecessor) in nodes.items():
            if predecessor is not None and predecessor not in nodes:
                raise ValueError("node predecessor is missing")

        # Second pass: predecessor edges form a functional graph (each node
        # points at at most one predecessor), so three-color walking detects
        # cycles in linear time overall.
        state: dict[NodeId, int] = {}  # 1 = on the current path, 2 = settled
        for start in nodes:
            if state.get(start) == 2:
                continue
            path: list[NodeId] = []
            cursor: NodeId | None = start
            while cursor is not None and state.get(cursor) != 2:
                if state.get(cursor) == 1:
                    raise ValueError("node predecessor cycle")
                state[cursor] = 1
                path.append(cursor)
                cursor = nodes[cursor][1]
            for visited in path:
                state[visited] = 2

        # A tombstone may only refer to an observed node...
        if not tombstones <= set(nodes):
            raise ValueError("tombstone references a node with no insert record")
        # ...and the counter must be at least the greatest observed sequence.
        # A Lamport clock is only ever advanced, never shared out with gaps, so
        # every counter at or above the maximum observed sequence is reachable
        # (this replica may simply have observed no insert of its own yet).
        if nodes and counter < max(sequence for sequence, _origin in nodes):
            raise ValueError(
                "counter must not be below the greatest observed node sequence"
            )

        restored = cls(replica_id)
        restored._counter = counter
        restored._nodes = nodes
        restored._tombstones = tombstones
        return restored

    def __repr__(self) -> str:
        return (
            f"RGA(replica_id={self._replica_id!r}, "
            f"values={self.values()!r})"
        )

"""Observed-remove set (ORSet) CRDT for removable string sets.

Every local ``add`` mints a unique tag ``(replica_id, counter)`` attached to
the added element. An element is visible as long as it owns at least one tag
that has not been observed by a ``remove``: ``remove(e)`` tombstones exactly
the tags visible on this replica at call time. Both the per-element tag map
and the tombstone set only ever grow, and merging takes their union, so
delivery is idempotent, commutative and associative, stale or duplicated
snapshots can never resurrect a removed add, and a fresh ``add`` after a
remove is never swallowed by the historical tombstone.
"""

from __future__ import annotations

Tag = tuple[str, int]


def _validate_replica_id(replica_id: object) -> str:
    if not isinstance(replica_id, str):
        raise TypeError("replica_id must be a non-empty string")
    if replica_id == "":
        raise ValueError("replica_id must be a non-empty string")
    return replica_id


def _validate_element(element: object) -> str:
    if not isinstance(element, str):
        raise TypeError("element must be a non-empty string")
    if element == "":
        raise ValueError("element must be a non-empty string")
    return element


def _parse_tag(raw_tag: object) -> Tag:
    """Parse a JSON-shape ``[origin_id, sequence]`` tag into a tuple."""
    if not isinstance(raw_tag, list):
        raise ValueError("tags must be [origin_id, sequence] lists")
    if len(raw_tag) != 2:
        raise ValueError("tags must be [origin_id, sequence] lists")
    origin, sequence = raw_tag
    if not isinstance(origin, str) or origin == "":
        raise ValueError("tag origin must be a non-empty string")
    if not isinstance(sequence, int) or isinstance(sequence, bool):
        raise ValueError("tag sequence must be an integer")
    if sequence < 1:
        raise ValueError("tag sequence must be greater than zero")
    return origin, sequence


class ORSet:
    """An observed-remove set of strings identified by a ``replica_id``."""

    def __init__(self, replica_id: str) -> None:
        self._replica_id = _validate_replica_id(replica_id)
        self._counter = 0
        self._adds: dict[str, set[Tag]] = {}
        self._removes: set[Tag] = set()

    @property
    def replica_id(self) -> str:
        return self._replica_id

    def add(self, element: str) -> None:
        """Record one new addition of ``element`` under a fresh unique tag."""
        element = _validate_element(element)
        self._counter += 1
        tag = (self._replica_id, self._counter)
        self._adds.setdefault(element, set()).add(tag)

    def remove(self, element: str) -> bool:
        """Tombstone the currently visible additions of ``element``.

        Returns ``True`` when at least one visible addition was withdrawn,
        ``False`` (without touching state) when the element is not visible.
        Only additions already observed by this replica are affected; a
        concurrent add of the same element on another replica stays visible.
        """
        element = _validate_element(element)
        tags = self._adds.get(element)
        if not tags:
            return False
        live = {tag for tag in tags if tag not in self._removes}
        if not live:
            return False
        self._removes.update(live)
        return True

    def contains(self, element: str) -> bool:
        """Return whether ``element`` currently has a visible addition."""
        element = _validate_element(element)
        tags = self._adds.get(element)
        if not tags:
            return False
        return any(tag not in self._removes for tag in tags)

    def elements(self) -> set[str]:
        """Return a fresh set of all currently visible elements."""
        return {
            element
            for element, tags in self._adds.items()
            if any(tag not in self._removes for tag in tags)
        }

    def merge(self, other: "ORSet") -> "ORSet":
        """Union the tag map and tombstone set with ``other``, in place.

        Returns ``self``; ``other`` is never modified. Repeated or reordered
        merges converge to the same state.

        Raises ``ValueError`` — leaving both states untouched — when the
        same tag is bound to different elements on the two sides. Such a
        conflict means two live replicas share a ``replica_id`` and minted
        colliding tags; unioning them would make the tag's ownership
        ambiguous and the merged state unrestorable.
        """
        if not isinstance(other, ORSet):
            raise TypeError("can only merge with another ORSet")
        # A tag identifies one add of one element; before unioning, verify
        # against the full add history of both sides that no tag changes
        # ownership across the two states. The check is total, so its
        # outcome never depends on dict iteration order.
        ownership: dict[Tag, str] = {}
        for element, tags in self._adds.items():
            for tag in tags:
                ownership[tag] = element
        conflicts: set[Tag] = set()
        for element, tags in other._adds.items():
            for tag in tags:
                owner = ownership.get(tag)
                if owner is not None and owner != element:
                    conflicts.add(tag)
        if conflicts:
            raise ValueError(
                "the same tag is bound to different elements: "
                + ", ".join(repr(tag) for tag in sorted(conflicts))
            )
        for element, tags in other._adds.items():
            self._adds.setdefault(element, set()).update(tags)
        self._removes.update(other._removes)
        # A state carrying our own replica id (e.g. a restored backup of this
        # replica) may know about more of our own adds; advance the counter
        # past every observed tag of ours so future tags stay unique.
        for tags in self._adds.values():
            for origin, sequence in tags:
                if origin == self._replica_id and sequence > self._counter:
                    self._counter = sequence
        return self

    def snapshot(self) -> dict[str, object]:
        """Return a fresh JSON-serializable snapshot of this set."""
        adds = {
            element: [[origin, sequence] for origin, sequence in sorted(tags)]
            for element, tags in sorted(self._adds.items())
        }
        removes = [
            [origin, sequence] for origin, sequence in sorted(self._removes)
        ]
        return {
            "replica_id": self._replica_id,
            "counter": self._counter,
            "adds": adds,
            "removes": removes,
        }

    @classmethod
    def from_snapshot(cls, snapshot: object) -> "ORSet":
        """Restore an ORSet from a :meth:`snapshot`-compatible dict."""
        if not isinstance(snapshot, dict):
            raise TypeError("snapshot must be a dict")

        if set(snapshot.keys()) != {
            "replica_id",
            "counter",
            "adds",
            "removes",
        }:
            raise ValueError(
                "snapshot must contain exactly 'replica_id', 'counter', "
                "'adds' and 'removes'"
            )

        replica_id = snapshot["replica_id"]
        if not isinstance(replica_id, str) or replica_id == "":
            raise ValueError("replica_id must be a non-empty string")

        counter = snapshot["counter"]
        if not isinstance(counter, int) or isinstance(counter, bool):
            raise ValueError("counter must be a non-negative integer")
        if counter < 0:
            raise ValueError("counter must be a non-negative integer")

        raw_adds = snapshot["adds"]
        if not isinstance(raw_adds, dict):
            raise ValueError("adds must be a dict")

        adds: dict[str, set[Tag]] = {}
        tag_owner: dict[Tag, str] = {}
        for element, raw_tags in raw_adds.items():
            if not isinstance(element, str) or element == "":
                raise ValueError("adds keys must be non-empty strings")
            if not isinstance(raw_tags, list):
                raise ValueError("adds values must be lists of tags")
            if not raw_tags:
                raise ValueError("adds values must not be empty tag lists")
            tags: set[Tag] = set()
            for raw_tag in raw_tags:
                tag = _parse_tag(raw_tag)
                owner = tag_owner.get(tag)
                if owner is not None and owner != element:
                    raise ValueError(
                        "the same tag is bound to different elements"
                    )
                tag_owner[tag] = element
                tags.add(tag)
            adds[element] = tags

        raw_removes = snapshot["removes"]
        if not isinstance(raw_removes, list):
            raise ValueError("removes must be a list of tags")
        removes: set[Tag] = set()
        for raw_tag in raw_removes:
            removes.add(_parse_tag(raw_tag))

        # Causal validity: a tombstone may only refer to an observed add...
        if not removes <= set(tag_owner):
            raise ValueError("removes references a tag with no matching add")
        # ...and the local counter must describe exactly this replica's own
        # observed add history (1..counter, no gaps, no unknown future tags).
        own_sequences = sorted(
            sequence
            for origin, sequence in tag_owner
            if origin == replica_id
        )
        if own_sequences != list(range(1, counter + 1)):
            raise ValueError(
                "counter is inconsistent with the replica's add history"
            )

        restored = cls(replica_id)
        restored._counter = counter
        restored._adds = adds
        restored._removes = removes
        return restored

    def __repr__(self) -> str:
        return (
            f"ORSet(replica_id={self._replica_id!r}, "
            f"elements={sorted(self.elements())!r})"
        )

"""Last-writer-wins register CRDT for offline-writable JSON values.

Each local ``assign`` first advances a logical clock and timestamps the write
with ``(logical_count, replica_id)``. Merging two registers keeps the entry
with the greater timestamp — count first, then the Unicode code point order
of the writing ``replica_id`` to break ties — so delivery is idempotent,
commutative and associative. Regardless of whose write wins, the receiver
also remembers the greatest logical count it has observed, so its next local
assignment is always later than every write seen so far.
"""

from __future__ import annotations

import copy
import math

Timestamp = tuple[int, str]


def _validate_replica_id(replica_id: object) -> str:
    if not isinstance(replica_id, str):
        raise TypeError("replica_id must be a non-empty string")
    if replica_id == "":
        raise ValueError("replica_id must be a non-empty string")
    return replica_id


def _is_json_value(value: object, stack: frozenset[int] = frozenset()) -> bool:
    """Return whether ``value`` is an assignable / JSON-round-trippable value.

    Accepts ``None``, booleans, strings, finite numbers and recursive lists
    and string-keyed dicts thereof. Rejects everything else (including
    non-finite floats and self-referential containers). Non-cyclic sharing of
    a container (e.g. ``[x, x]``) stays acceptable, as for ``json.dumps``.
    """
    if value is None or isinstance(value, (str, bool, int)):
        return True
    if isinstance(value, float):
        return math.isfinite(value)
    if isinstance(value, (list, dict)):
        marker = id(value)
        if marker in stack:
            return False
        stack = stack | {marker}
        if isinstance(value, list):
            return all(_is_json_value(item, stack) for item in value)
        return all(
            isinstance(key, str) and _is_json_value(item, stack)
            for key, item in value.items()
        )
    return False


def _same_value(left: object, right: object) -> bool:
    """Structurally compare two already-validated stored values.

    Booleans are distinct from numbers (mirroring the JSON ``true``/``false``
    vs number distinction), while ``int`` and ``float`` compare by numeric
    equality. Lists and dicts recurse.
    """
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left == right
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return left == right
    if isinstance(left, str) or isinstance(right, str):
        return isinstance(left, str) and isinstance(right, str) and left == right
    if left is None or right is None:
        return left is None and right is None
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(
            _same_value(a, b) for a, b in zip(left, right)
        )
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(
            _same_value(left[key], right[key]) for key in left
        )
    return False


class LWWRegister:
    """A last-writer-wins register identified by a ``replica_id``.

    A fresh instance holds no value: :meth:`has_value` is ``False`` and
    :meth:`value` raises ``LookupError`` until the first :meth:`assign`.
    """

    def __init__(self, replica_id: str) -> None:
        self._replica_id = _validate_replica_id(replica_id)
        # Greatest logical count ever observed (locally or via merge).
        self._clock = 0
        # Winning timestamp and its stored value, or None / unset before any
        # observed write.
        self._timestamp: Timestamp | None = None
        self._value: object = None
        self._has_value = False

    @property
    def replica_id(self) -> str:
        return self._replica_id

    def has_value(self) -> bool:
        """Return whether this register currently carries a written value."""
        return self._has_value

    def value(self) -> object:
        """Return an independent deep copy of the current value.

        Raises ``LookupError`` when no write has been observed yet.
        """
        if not self._has_value:
            raise LookupError("LWWRegister has no value yet")
        return copy.deepcopy(self._value)

    def assign(self, value: object) -> None:
        """Locally assign ``value`` under a fresh, strictly greater timestamp."""
        if not _is_json_value(value):
            raise TypeError(
                "value must be a JSON value: null, bool, str, finite number, "
                "or a recursive list / string-keyed dict of such values"
            )
        self._clock += 1
        self._timestamp = (self._clock, self._replica_id)
        # Deep copy so later caller mutations of the input cannot leak in.
        self._value = copy.deepcopy(value)
        self._has_value = True

    def merge(self, other: "LWWRegister") -> "LWWRegister":
        """Absorb ``other``'s state in place, keeping the winning entry.

        Returns ``self``; ``other`` is never modified. The winner is chosen by
        timestamp: greater count wins, with the Unicode code point order of
        the writing ``replica_id`` breaking ties. Either way, the greatest
        observed logical count is remembered.

        Raises ``ValueError`` — leaving both registers untouched — when the
        very same timestamp is bound to two structurally different values,
        which means two live replicas share a ``replica_id`` and minted
        colliding timestamps.
        """
        if not isinstance(other, LWWRegister):
            raise TypeError("can only merge with another LWWRegister")

        # Resolve the outcome before touching any state so a conflict leaves
        # both registers unchanged.
        adopt_value: object = None
        adopt_timestamp: Timestamp | None = None
        conflict = False
        if other._has_value:
            if not self._has_value:
                adopt_timestamp = other._timestamp
                adopt_value = other._value
            else:
                assert self._timestamp is not None
                assert other._timestamp is not None
                if other._timestamp > self._timestamp:
                    adopt_timestamp = other._timestamp
                    adopt_value = other._value
                elif other._timestamp == self._timestamp:
                    conflict = not _same_value(other._value, self._value)

        if conflict:
            raise ValueError(
                "the same timestamp is bound to structurally different values"
            )

        if other._clock > self._clock:
            self._clock = other._clock
        if adopt_timestamp is not None:
            self._timestamp = adopt_timestamp
            self._value = copy.deepcopy(adopt_value)
            self._has_value = True
        return self

    def snapshot(self) -> dict[str, object]:
        """Return a fresh JSON-serializable snapshot of this register."""
        if not self._has_value:
            entry: object = None
        else:
            assert self._timestamp is not None
            entry = {
                "timestamp": [self._timestamp[0], self._timestamp[1]],
                "value": copy.deepcopy(self._value),
            }
        return {
            "replica_id": self._replica_id,
            "clock": self._clock,
            "entry": entry,
        }

    @classmethod
    def from_snapshot(cls, snapshot: object) -> "LWWRegister":
        """Restore a register from a :meth:`snapshot`-compatible dict."""
        if not isinstance(snapshot, dict):
            raise TypeError("snapshot must be a dict")

        if set(snapshot.keys()) != {"replica_id", "clock", "entry"}:
            raise ValueError(
                "snapshot must contain exactly 'replica_id', 'clock' and "
                "'entry'"
            )

        replica_id = snapshot["replica_id"]
        if not isinstance(replica_id, str) or replica_id == "":
            raise ValueError("replica_id must be a non-empty string")

        clock = snapshot["clock"]
        if not isinstance(clock, int) or isinstance(clock, bool):
            raise ValueError("clock must be a non-negative integer")
        if clock < 0:
            raise ValueError("clock must be a non-negative integer")

        raw_entry = snapshot["entry"]
        timestamp: Timestamp | None = None
        value: object = None
        if raw_entry is not None:
            if not isinstance(raw_entry, dict):
                raise ValueError("entry must be null or a timestamped entry")
            if set(raw_entry.keys()) != {"timestamp", "value"}:
                raise ValueError(
                    "entry must contain exactly 'timestamp' and 'value'"
                )

            raw_timestamp = raw_entry["timestamp"]
            if not isinstance(raw_timestamp, list) or len(raw_timestamp) != 2:
                raise ValueError("timestamp must be a [count, origin_id] list")
            count, origin = raw_timestamp
            if not isinstance(count, int) or isinstance(count, bool):
                raise ValueError("timestamp count must be an integer")
            if count < 1:
                raise ValueError("timestamp count must be greater than zero")
            if not isinstance(origin, str) or origin == "":
                raise ValueError("timestamp origin must be a non-empty string")
            if count > clock:
                raise ValueError("timestamp count must not exceed the clock")

            raw_value = raw_entry["value"]
            if not _is_json_value(raw_value):
                raise ValueError("entry value must be a JSON value")

            timestamp = (count, origin)
            value = copy.deepcopy(raw_value)

        restored = cls(replica_id)
        restored._clock = clock
        restored._timestamp = timestamp
        restored._value = value
        restored._has_value = raw_entry is not None
        return restored

    def __repr__(self) -> str:
        if not self._has_value:
            return f"LWWRegister(replica_id={self._replica_id!r}, <no value>)"
        return (
            f"LWWRegister(replica_id={self._replica_id!r}, "
            f"timestamp={self._timestamp!r}, value={self._value!r})"
        )

"""Grow-only counter CRDT.

Each replica keeps a per-replica non-negative integer component. The local
replica only increments its own component; merging takes the component-wise
maximum across replicas.
"""

from __future__ import annotations


def _validate_replica_id(replica_id: object) -> str:
    if not isinstance(replica_id, str):
        raise TypeError("replica_id must be a non-empty string")
    if replica_id == "":
        raise ValueError("replica_id must be a non-empty string")
    return replica_id


def _validate_amount(amount: object) -> int:
    if not isinstance(amount, int) or isinstance(amount, bool):
        raise TypeError("amount must be an integer")
    if amount <= 0:
        raise ValueError("amount must be greater than zero")
    return amount


class GCounter:
    """A grow-only counter identified by a local ``replica_id``."""

    def __init__(self, replica_id: str) -> None:
        self._replica_id = _validate_replica_id(replica_id)
        self._counts: dict[str, int] = {}

    @property
    def replica_id(self) -> str:
        return self._replica_id

    def increment(self, amount: int = 1) -> None:
        """Increase the local replica's component by ``amount`` (default 1)."""
        amount = _validate_amount(amount)
        self._counts[self._replica_id] = (
            self._counts.get(self._replica_id, 0) + amount
        )

    def value(self) -> int:
        """Return the sum of all known replica components."""
        return sum(self._counts.values())

    def merge(self, other: "GCounter") -> "GCounter":
        """Take the component-wise maximum with ``other``, in place.

        Returns ``self``; ``other`` is never modified. Repeated or reordered
        merges converge to the same state.
        """
        if not isinstance(other, GCounter):
            raise TypeError("can only merge with another GCounter")
        for replica_id, other_count in other._counts.items():
            current = self._counts.get(replica_id, 0)
            if other_count > current:
                self._counts[replica_id] = other_count
        return self

    def snapshot(self) -> dict[str, object]:
        """Return a fresh JSON-serializable snapshot of this counter."""
        counts = {key: self._counts[key] for key in sorted(self._counts)}
        return {"replica_id": self._replica_id, "counts": counts}

    @classmethod
    def from_snapshot(cls, snapshot: object) -> "GCounter":
        """Restore a counter from a :meth:`snapshot`-compatible dict."""
        if not isinstance(snapshot, dict):
            raise TypeError("snapshot must be a dict")

        keys = set(snapshot.keys())
        if keys != {"replica_id", "counts"}:
            raise ValueError(
                "snapshot must contain exactly 'replica_id' and 'counts'"
            )

        replica_id = snapshot["replica_id"]
        if not isinstance(replica_id, str) or replica_id == "":
            raise ValueError("replica_id must be a non-empty string")

        counts = snapshot["counts"]
        if not isinstance(counts, dict):
            raise ValueError("counts must be a dict")

        restored: dict[str, int] = {}
        for key, component in counts.items():
            if not isinstance(key, str) or key == "":
                raise ValueError("counts keys must be non-empty strings")
            if (
                not isinstance(component, int)
                or isinstance(component, bool)
                or component < 0
            ):
                raise ValueError(
                    "counts values must be non-negative integers"
                )
            restored[key] = component

        counter = cls(replica_id)
        counter._counts = restored
        return counter

    def __repr__(self) -> str:
        return f"GCounter(replica_id={self._replica_id!r}, value={self.value()})"

input.content:
"""Model-based, seed-reproducible convergence tests for the public CRDT API.

For each CRDT type exposed by the current baseline (``GCounter``, ``ORSet``,
``LWWRegister``, ``RGA``) this suite runs randomized scenarios that:

* start three or more replicas (distinct participant ids) from the same empty
  initial state and let them edit concurrently while "offline";
* record every local operation and every sync message in an explicit trace;
* shuffle cross-replica delivery order, duplicate messages, split batches
  (a snapshot fanned out to several replicas is delivered piecemeal) and
  delay arbitrary messages until a final reconnect phase;
* reconnect by repeatedly applying the public ``merge`` entry point until
  every queued message is drained and a fixed point is reached;
* check the originating replica against an independent abstract model after
  every local operation, and check every receiver after every delivery;
* after all messages are delivered, compare the public value *and* a
  canonical serialization of every replica, and probe idempotence
  (redelivering a stale snapshot and merging the same state twice must be
  no-ops).

The abstract models below are small, self-contained re-implementations
written directly from each type's documented contract; they share no code
with the production merge paths. The ORSet model, for example, tracks
harness-assigned addition ids rather than the production tag scheme.

Everything is driven through the public API only (operations, ``merge``,
``snapshot``/``from_snapshot`` and the public readers); no private fields
are inspected.

Determinism: a scenario is a pure function of ``(crdt_type, seed, n_ops,
replicas)`` — the same seed, initial state and operation count reproduce the
exact same participants, operations and delivery trace. On failure the
report includes the seed, the CRDT type, the original operation and delivery
traces, the first divergence position, and an automatically shrunk event
trace (delta-debugging over the recorded events) that still reproduces a
divergence and can be replayed directly via ``replay_events``.

Compaction: the current baseline exposes no tombstone-compaction entry point
on any of the four types, so — per the task constraints — no compaction
behavior is fabricated or tested here. Existing deterministic example tests
and the public exception contract are untouched.
"""

from __future__ import annotations

import copy
import json
import random
import unittest

from crdt_sync import GCounter, LWWRegister, ORSet, RGA

REPLICAS = ("alpha", "beta", "gamma")
REAL_CLASSES = {
    "gcounter": GCounter,
    "orset": ORSet,
    "lww": LWWRegister,
    "rga": RGA,
}
CRDT_TYPES = tuple(REAL_CLASSES)

ORSET_POOL = ("red", "green", "blue", "cat", "dog")
RGA_POOL = ("a", "b", "c", "d")
LWW_POOL = (
    None,
    True,
    False,
    "x",
    "yz",
    0,
    7,
    2.5,
    [1, "a"],
    {"k": [1, 2]},
    {"a": None},
)

SEEDS_PER_TYPE = 6
OPS_PER_SCENARIO = 60
MAX_SYNC_ROUNDS = 8
SHRINK_BUDGET = 400  # max replay attempts while minimizing a failing trace


# ---------------------------------------------------------------------------
# Independent abstract models (spec re-implementations, no production code).
# ---------------------------------------------------------------------------


class GCounterModel:
    """Per-component counts; merge takes the component-wise maximum."""

    def __init__(self) -> None:
        self.counts: dict[str, int] = {}

    def increment(self, replica: str, amount: int) -> None:
        self.counts[replica] = self.counts.get(replica, 0) + amount

    def merge(self, other: "GCounterModel") -> None:
        for replica, count in other.counts.items():
            if count > self.counts.get(replica, 0):
                self.counts[replica] = count

    def value(self) -> int:
        return sum(self.counts.values())


class ORSetModel:
    """Adds carry harness-minted addition ids; removes tombstone observed ids."""

    def __init__(self) -> None:
        self.element_of: dict[int, str] = {}
        self.known: set[int] = set()
        self.removed: set[int] = set()

    def add(self, oid: int, element: str) -> None:
        self.element_of[oid] = element
        self.known.add(oid)

    def remove(self, element: str) -> bool:
        live = {
            oid
            for oid in self.known
            if oid not in self.removed and self.element_of[oid] == element
        }
        self.removed |= live
        return bool(live)

    def merge(self, other: "ORSetModel") -> None:
        for oid in other.known - self.known:
            self.element_of[oid] = other.element_of[oid]
        self.known |= other.known
        self.removed |= other.removed

    def elements(self) -> set[str]:
        return {
            self.element_of[oid]
            for oid in self.known
            if oid not in self.removed
        }


class LWWModel:
    """Winner is the greatest (count, replica) timestamp; clock is the max seen."""

    def __init__(self) -> None:
        self.clock = 0
        self.timestamp: tuple[int, str] | None = None
        self.stored: object = None
        self.has = False

    def assign(self, replica: str, value: object) -> None:
        self.clock += 1
        self.timestamp = (self.clock, replica)
        self.stored = copy.deepcopy(value)
        self.has = True

    def merge(self, other: "LWWModel") -> None:
        if other.has and (
            not self.has
            or (other.timestamp is not None and other.timestamp > self.timestamp)
        ):
            self.timestamp = other.timestamp
            self.stored = copy.deepcopy(other.stored)
            self.has = True
        if other.clock > self.clock:
            self.clock = other.clock

    def view(self) -> tuple[bool, object]:
        return (self.has, copy.deepcopy(self.stored) if self.has else None)


class RGAModel:
    """Spec weave: siblings ordered by id descending, branches contiguous."""

    def __init__(self, replica: str) -> None:
        self.replica = replica
        self.counter = 0
        self.nodes: dict[tuple[int, str], tuple[str, tuple[int, str] | None]] = {}
        self.tombstones: set[tuple[int, str]] = set()

    def _visible_ids(self) -> list[tuple[int, str]]:
        children: dict[tuple[int, str] | None, list[tuple[int, str]]] = {}
        for node_id, (_value, predecessor) in self.nodes.items():
            children.setdefault(predecessor, []).append(node_id)
        for siblings in children.values():
            siblings.sort(reverse=True)
        ordered: list[tuple[int, str]] = []
        stack = list(reversed(children.get(None, ())))
        while stack:
            node_id = stack.pop()
            ordered.append(node_id)
            stack.extend(reversed(children.get(node_id, ())))
        return [n for n in ordered if n not in self.tombstones]

    def values(self) -> list[str]:
        return [self.nodes[n][0] for n in self._visible_ids()]

    def insert(self, index: int, value: str) -> None:
        visible = self._visible_ids()
        if index < 0 or index > len(visible):
            raise IndexError("model insert index out of range")
        predecessor = visible[index - 1] if index > 0 else None
        self.counter += 1
        self.nodes[(self.counter, self.replica)] = (value, predecessor)

    def delete(self, index: int) -> str:
        visible = self._visible_ids()
        if index < 0 or index >= len(visible):
            raise IndexError("model delete index out of range")
        node_id = visible[index]
        self.tombstones.add(node_id)
        return self.nodes[node_id][0]

    def merge(self, other: "RGAModel") -> None:
        for node_id, record in other.nodes.items():
            if node_id not in self.nodes:
                self.nodes[node_id] = record
        self.tombstones |= other.tombstones
        if other.counter > self.counter:
            self.counter = other.counter


MODEL_FACTORIES = {
    "gcounter": lambda replica: GCounterModel(),
    "orset": lambda replica: ORSetModel(),
    "lww": lambda replica: LWWModel(),
    "rga": lambda replica: RGAModel(replica),
}


# ---------------------------------------------------------------------------
# Divergence and engine plumbing.
# ---------------------------------------------------------------------------


class Divergence(Exception):
    """A mismatch between the production CRDT and the abstract model."""

    def __init__(self, where: str, detail: str) -> None:
        super().__init__(f"{where}: {detail}")
        self.where = where
        self.detail = detail
        self.events: list[dict] | None = None


class SkipOp(Exception):
    """Raised when a replayed (shrunk) operation is no longer legal."""


class Engine:
    """Holds the real replicas, their models and the pending message queue."""

    def __init__(self, crdt_type: str, replicas) -> None:
        self.type = crdt_type
        self.replicas = tuple(replicas)
        self.real = {r: REAL_CLASSES[crdt_type](r) for r in self.replicas}
        self.model = {r: MODEL_FACTORIES[crdt_type](r) for r in self.replicas}
        # msg id -> [dst, wire snapshot, model payload, remaining copies]
        self.queue: dict[int, list] = {}
        self.next_msg = 0
        self.next_oid = 0


def restore(crdt_type: str, snapshot: dict):
    """Restore a snapshot after a full JSON round trip (simulated wire)."""
    return REAL_CLASSES[crdt_type].from_snapshot(
        json.loads(json.dumps(snapshot))
    )


def public_view(crdt_type: str, real) -> object:
    if crdt_type == "gcounter":
        return real.value()
    if crdt_type == "orset":
        return sorted(real.elements())
    if crdt_type == "lww":
        return (real.has_value(), real.value() if real.has_value() else None)
    return list(real.values())


def model_view(crdt_type: str, model) -> object:
    if crdt_type == "gcounter":
        return model.value()
    if crdt_type == "orset":
        return sorted(model.elements())
    if crdt_type == "lww":
        return model.view()
    return model.values()


def canonical_form(crdt_type: str, real) -> str:
    """Canonical serialization used for cross-replica comparison.

    ``replica_id`` is always replica-local. The ORSet ``counter`` only
    describes the replica's *own* addition history (merges never adopt a
    peer's counter), so it legitimately differs between converged replicas
    and is excluded. The RGA counter and the LWW clock are Lamport-style
    maxima that do converge, so they stay in.
    """
    snap = json.loads(json.dumps(real.snapshot()))
    snap.pop("replica_id", None)
    if crdt_type == "orset":
        snap.pop("counter", None)
    return json.dumps(snap, sort_keys=True)


def check_view(ctx: Engine, replica: str, where: str) -> None:
    expected = model_view(ctx.type, ctx.model[replica])
    actual = public_view(ctx.type, ctx.real[replica])
    if expected != actual:
        raise Divergence(
            where,
            f"replica {replica!r} view diverged: "
            f"expected (model) {expected!r}, actual (crdt) {actual!r}",
        )


def apply_op(ctx: Engine, ev: dict, where: str) -> None:
    replica = ev["replica"]
    real = ctx.real[replica]
    model = ctx.model[replica]
    if ctx.type == "gcounter":
        real.increment(ev["amount"])
        model.increment(replica, ev["amount"])
    elif ctx.type == "orset":
        if ev["op"] == "add":
            real.add(ev["element"])
            model.add(ev["oid"], ev["element"])
        else:
            got = real.remove(ev["element"])
            want = model.remove(ev["element"])
            if got != want:
                raise Divergence(
                    where,
                    f"replica {replica!r} remove({ev['element']!r}) returned "
                    f"{got!r}, model expected {want!r}",
                )
    elif ctx.type == "lww":
        real.assign(copy.deepcopy(ev["value"]))
        model.assign(replica, ev["value"])
    else:  # rga
        length = len(real.values())
        if ev["op"] == "insert":
            if ev["index"] < 0 or ev["index"] > length:
                raise SkipOp
            real.insert(ev["index"], ev["value"])
            try:
                model.insert(ev["index"], ev["value"])
            except IndexError:
                raise Divergence(
                    where,
                    f"replica {replica!r} model rejected insert index "
                    f"{ev['index']} that the crdt accepted",
                )
        else:
            if ev["index"] < 0 or ev["index"] >= length:
                raise SkipOp
            got = real.delete(ev["index"])
            try:
                want = model.delete(ev["index"])
            except IndexError:
                raise Divergence(
                    where,
                    f"replica {replica!r} model rejected delete index "
                    f"{ev['index']} that the crdt accepted",
                )
            if got != want:
                raise Divergence(
                    where,
                    f"replica {replica!r} delete({ev['index']}) returned "
                    f"{got!r}, model expected {want!r}",
                )


def apply_event(ctx: Engine, events: list[dict], i: int) -> None:
    ev = events[i]
    where = f"event {i} {json.dumps(ev, sort_keys=True)}"
    kind = ev["ev"]
    if kind == "op":
        apply_op(ctx, ev, where)
        check_view(ctx, ev["replica"], where)
    elif kind == "send":
        ctx.queue[ev["msg"]] = [
            ev["dst"],
            json.loads(json.dumps(ctx.real[ev["src"]].snapshot())),
            copy.deepcopy(ctx.model[ev["src"]]),
            ev["copies"],
        ]
    else:  # deliver
        entry = ctx.queue.get(ev["msg"])
        if entry is None:
            return  # only possible in shrunk replays
        dst, wire, model_payload, _copies = entry
        ctx.real[dst].merge(restore(ctx.type, wire))
        ctx.model[dst].merge(copy.deepcopy(model_payload))
        entry[3] -= 1
        if entry[3] == 0:
            del ctx.queue[ev["msg"]]
        check_view(ctx, dst, where)


def post_phase(ctx: Engine) -> dict[str, str]:
    """Reconnect: sync to a fixed point, then run the final assertions.

    Returns the per-replica canonical forms (all identical on success).
    """
    replicas = sorted(ctx.real)
    stale = json.loads(json.dumps(ctx.real[replicas[0]].snapshot()))

    converged = False
    for _round in range(MAX_SYNC_ROUNDS):
        for src in replicas:
            wire = json.loads(json.dumps(ctx.real[src].snapshot()))
            model_payload = copy.deepcopy(ctx.model[src])
            for dst in replicas:
                if src == dst:
                    continue
                ctx.real[dst].merge(restore(ctx.type, wire))
                ctx.model[dst].merge(copy.deepcopy(model_payload))
        canonicals = {r: canonical_form(ctx.type, ctx.real[r]) for r in replicas}
        if len(set(canonicals.values())) == 1:
            converged = True
            break
    if not converged:
        detail = "; ".join(
            f"{r}: {c}" for r, c in sorted(canonicals.items())
        )
        raise Divergence(
            "post:converge",
            f"replicas did not converge after {MAX_SYNC_ROUNDS} sync "
            f"rounds: {detail}",
        )

    for replica in replicas:
        check_view(ctx, replica, "post:view")

    # Idempotence: merging the same state twice in a row changes nothing.
    for replica in replicas:
        before = canonical_form(ctx.type, ctx.real[replica])
        snap = json.loads(json.dumps(ctx.real[replica].snapshot()))
        ctx.real[replica].merge(restore(ctx.type, snap))
        ctx.real[replica].merge(restore(ctx.type, snap))
        after = canonical_form(ctx.type, ctx.real[replica])
        if after != before:
            raise Divergence(
                "post:idempotence",
                f"replica {replica!r} changed after merging the same state "
                f"twice: before {before}, after {after}",
            )

    # Stale redelivery: an old pre-reconnect snapshot must be a no-op.
    for replica in replicas:
        before = canonical_form(ctx.type, ctx.real[replica])
        ctx.real[replica].merge(restore(ctx.type, stale))
        after = canonical_form(ctx.type, ctx.real[replica])
        if after != before:
            raise Divergence(
                "post:stale-redelivery",
                f"replica {replica!r} changed after redelivering a stale "
                f"snapshot: before {before}, after {after}",
            )

    return {r: canonical_form(ctx.type, ctx.real[r]) for r in replicas}


# ---------------------------------------------------------------------------
# Scenario generation (seeded) and replay (seed-free, trace-driven).
# ---------------------------------------------------------------------------


def _gen_op(rng: random.Random, ctx: Engine, replica: str) -> dict:
    if ctx.type == "gcounter":
        return {
            "ev": "op",
            "op": "inc",
            "replica": replica,
            "amount": rng.randint(1, 5),
        }
    if ctx.type == "orset":
        visible = sorted(ctx.real[replica].elements())
        if rng.random() < 0.4:
            if visible and rng.random() < 0.75:
                element = rng.choice(visible)
            else:
                element = rng.choice(ORSET_POOL)
            return {"ev": "op", "op": "remove", "replica": replica,
                    "element": element}
        oid = ctx.next_oid
        ctx.next_oid += 1
        return {"ev": "op", "op": "add", "replica": replica,
                "element": rng.choice(ORSET_POOL), "oid": oid}
    if ctx.type == "lww":
        return {"ev": "op", "op": "assign", "replica": replica,
                "value": copy.deepcopy(rng.choice(LWW_POOL))}
    # rga
    values = ctx.real[replica].values()
    if values and rng.random() < 0.35:
        return {"ev": "op", "op": "delete", "replica": replica,
                "index": rng.randrange(len(values))}
    return {"ev": "op", "op": "insert", "replica": replica,
            "index": rng.randint(0, len(values)),
            "value": rng.choice(RGA_POOL)}


def generate_and_run(
    crdt_type: str, seed: int, n_ops: int, replicas=REPLICAS
) -> tuple[list[dict], dict[str, str]]:
    """Generate a seeded scenario, execute it with checks, return its trace.

    The trace plus the post-phase fully determine the final state, so the
    returned ``(events, canonicals)`` pair is reproducible from the seed.
    """
    rng = random.Random(
        f"model-based|{crdt_type}|{seed}|{n_ops}|{','.join(replicas)}"
    )
    ctx = Engine(crdt_type, replicas)
    events: list[dict] = []
    try:
        for _step in range(n_ops):
            roll = rng.random()
            if roll < 0.8 or not ctx.queue:
                if roll < 0.55 or not ctx.queue:
                    ev = _gen_op(rng, ctx, rng.choice(ctx.replicas))
                    events.append(ev)
                    apply_event(ctx, events, len(events) - 1)
                else:
                    src = rng.choice(ctx.replicas)
                    others = [r for r in ctx.replicas if r != src]
                    # One fan-out batch; delivery below splits it piecemeal.
                    for dst in rng.sample(others, rng.randint(1, len(others))):
                        copies = (
                            1
                            + int(rng.random() < 0.35)
                            + int(rng.random() < 0.15)
                        )
                        ev = {
                            "ev": "send",
                            "src": src,
                            "dst": dst,
                            "msg": ctx.next_msg,
                            "copies": copies,
                        }
                        ctx.next_msg += 1
                        events.append(ev)
                        apply_event(ctx, events, len(events) - 1)
            else:
                ids = sorted(ctx.queue)
                for msg in rng.sample(ids, rng.randint(1, min(3, len(ids)))):
                    ev = {"ev": "deliver", "msg": msg}
                    events.append(ev)
                    apply_event(ctx, events, len(events) - 1)
        # Reconnect: drain every delayed message, in random order.
        while ctx.queue:
            ev = {"ev": "deliver", "msg": rng.choice(sorted(ctx.queue))}
            events.append(ev)
            apply_event(ctx, events, len(events) - 1)
        canonicals = post_phase(ctx)
    except Divergence as div:
        div.events = events
        raise
    return events, canonicals


def replay_events(
    crdt_type: str, events, replicas=REPLICAS
) -> dict[str, str]:
    """Replay a recorded trace (no randomness) and run all checks.

    Operations that became illegal through trace shrinking are skipped;
    everything else must behave exactly as in the original run.
    """
    ctx = Engine(crdt_type, replicas)
    events = list(events)
    for i in range(len(events)):
        try:
            apply_event(ctx, events, i)
        except SkipOp:
            continue
    return post_phase(ctx)


# ---------------------------------------------------------------------------
# Shrinking: delta-debug the recorded trace down to a shorter failing one.
# ---------------------------------------------------------------------------


def minimize(crdt_type: str, replicas, events: list[dict]) -> list[dict]:
    """Return a 1-minimal-ish subsequence of ``events`` that still diverges."""
    attempts = [0]

    def fails(candidate: list[dict]) -> bool:
        if not candidate or attempts[0] >= SHRINK_BUDGET:
            return False
        attempts[0] += 1
        try:
            replay_events(crdt_type, candidate, replicas=replicas)
        except Divergence:
            return True
        return False

    events = list(events)
    if not fails(events):
        return events
    n = 2
    while len(events) >= 2 and attempts[0] < SHRNK_BUDGET if False else True:
        chunk = max(1, len(events) // n)
        reduced = False
        i = 0
        while i < len(events):
            candidate = events[:i] + events[i + chunk:]
            if fails(candidate):
                events = candidate
                reduced = True
                break
            i += chunk
        if attempts[0] >= SHRINK_BUDGET:
            break
        if reduced:
            n = max(2, n - 1)
        else:
            if chunk == 1:
                break
            n = min(len(events), n * 2)
    return events


# ---------------------------------------------------------------------------
# Failure reporting.
# ---------------------------------------------------------------------------


def _render_events(events: list[dict]) -> str:
    lines = ["  operation trace:"]
    for i, ev in enumerate(events):
        if ev["ev"] == "op":
            lines.append(f"    {i:4d} {json.dumps(ev, sort_keys=True)}")
    lines.append("  delivery trace:")
    for i, ev in enumerate(events):
        if ev["ev"] != "op":
            lines.append(f"    {i:4d} {json.dumps(ev, sort_keys=True)}")
    return "\n".join(lines)


def build_report(
    crdt_type: str, seed: int, n_ops: int, replicas, div: Divergence
) -> str:
    events = div.events or []
    shrunk = minimize(crdt_type, replicas, events)
    try:
        replay_events(crdt_type, shrunk, replicas=replicas)
        shrunk_outcome = "<shrunk trace did not diverge on replay>"
    except Divergence as div2:
        shrunk_outcome = f"{div2.where}: {div2.detail}"
    return "\n".join(
        [
            "model-based convergence failure",
            f"seed: {seed}",
            f"crdt type: {crdt_type}",
            f"operations requested: {n_ops}",
            f"first divergence: {div.where}: {div.detail}",
            "",
            f"original trace ({len(events)} events):",
            _render_events(events),
            "",
            f"shrunk failing trace ({len(shrunk)} events):",
            _render_events(shrunk),
            "",
            f"shrunk divergence: {shrunk_outcome}",
            "",
            "replay the shrunk trace with:",
            f"  replay_events({crdt_type!r}, "
            f"{json.dumps(shrunk, sort_keys=True)})",
        ]
    )


# ---------------------------------------------------------------------------
# Tests.
# ---------------------------------------------------------------------------


class ModelBasedScenarioTests(unittest.TestCase):
    def _run_type(self, crdt_type: str) -> None:
        for seed in range(SEEDS_PER_TYPE):
            with self.subTest(crdt=crdt_type, seed=seed):
                try:
                    generate_and_run(
                        crdt_type, seed, OPS_PER_SCENARIO if False else OPS_PER_SCENARIO, REPLICAS
                    )
                except Divergence as div:
                    self.fail(
                        build_report(
                            crdt_type, seed, OPS_PER_SCENARIO, REPLICAS, div
                        )
                    )

    def test_gcounter_scenarios(self) -> None:
        self._run_type("gcounter")

    def test_orset_scenarios(self) -> None:
        self._run_type("orset")

    def test_lww_scenarios(self) -> None:
        self._run_type("lww")

    def test_rga_scenarios(self) -> None:
        self._run_type("rga")

    def test_same_seed_reproduces_trace(self) -> None:
        for crdt_type in CRDT_TYPES:
            with self.subTest(crdt=crdt_type):
                first, _ = generate_and_run(crdt_type, 101, 40, REPLICAS)
                second, _ = generate_and_run(crdt_type, 101, 40, REPLICAS)
                self.assertEqual(first, second)

    def test_different_seeds_diverge(self) -> None:
        first, _ = generate_and_run("rga", 1, 40, REPLICAS)
        second, _ = generate_and_run("rga", 2, 40, REPLICAS)
        self.assertNotEqual(first, second)

    def test_replay_reproduces_final_state(self) -> None:
        for crdt_type in CRDT_TYPES:
            with self.subTest(crdt=crdt_type):
                events, generated = generate_and_run(crdt_type, 7, 40, REPLICAS)
                replayed = replay_events(crdt_type, events)
                self.assertEqual(generated, replayed)


if __name__ == "__main__":
    unittest.main()

toolUseResult.content:
"""Model-based, seed-reproducible convergence tests for the public CRDT API.

For each CRDT type exposed by the current baseline (``GCounter``, ``ORSet``,
``LWWRegister``, ``RGA``) this suite runs randomized scenarios that:

* start three or more replicas (distinct participant ids) from the same empty
  initial state and let them edit concurrently while "offline";
* record every local operation and every sync message in an explicit trace;
* shuffle cross-replica delivery order, duplicate messages, split batches
  (a snapshot fanned out to several replicas is delivered piecemeal) and
  delay arbitrary messages until a final reconnect phase;
* reconnect by repeatedly applying the public ``merge`` entry point until
  every queued message is drained and a fixed point is reached;
* check the originating replica against an independent abstract model after
  every local operation, and check every receiver after every delivery;
* after all messages are delivered, compare the public value *and* a
  canonical serialization of every replica, and probe idempotence
  (redelivering a stale snapshot and merging the same state twice must be
  no-ops).

The abstract models below are small, self-contained re-implementations
written directly from each type's documented contract; they share no code
with the production merge paths. The ORSet model, for example, tracks
harness-assigned addition ids rather than the production tag scheme.

Everything is driven through the public API only (operations, ``merge``,
``snapshot``/``from_snapshot`` and the public readers); no private fields
are inspected.

Determinism: a scenario is a pure function of ``(crdt_type, seed, n_ops,
replicas)`` — the same seed, initial state and operation count reproduce the
exact same participants, operations and delivery trace. On failure the
report includes the seed, the CRDT type, the original operation and delivery
traces, the first divergence position, and an automatically shrunk event
trace (delta-debugging over the recorded events) that still reproduces a
divergence and can be replayed directly via ``replay_events``.

Compaction: the current baseline exposes no tombstone-compaction entry point
on any of the four types, so — per the task constraints — no compaction
behavior is fabricated or tested here. Existing deterministic example tests
and the public exception contract are untouched.
"""

from __future__ import annotations

import copy
import json
import random
import unittest

from crdt_sync import GCounter, LWWRegister, ORSet, RGA

REPLICAS = ("alpha", "beta", "gamma")
REAL_CLASSES = {
    "gcounter": GCounter,
    "orset": ORSet,
    "lww": LWWRegister,
    "rga": RGA,
}
CRDT_TYPES = tuple(REAL_CLASSES)

ORSET_POOL = ("red", "green", "blue", "cat", "dog")
RGA_POOL = ("a", "b", "c", "d")
LWW_POOL = (
    None,
    True,
    False,
    "x",
    "yz",
    0,
    7,
    2.5,
    [1, "a"],
    {"k": [1, 2]},
    {"a": None},
)

SEEDS_PER_TYPE = 6
OPS_PER_SCENARIO = 60
MAX_SYNC_ROUNDS = 8
SHRINK_BUDGET = 400  # max replay attempts while minimizing a failing trace


# ---------------------------------------------------------------------------
# Independent abstract models (spec re-implementations, no production code).
# ---------------------------------------------------------------------------


class GCounterModel:
    """Per-component counts; merge takes the component-wise maximum."""

    def __init__(self) -> None:
        self.counts: dict[str, int] = {}

    def increment(self, replica: str, amount: int) -> None:
        self.counts[replica] = self.counts.get(replica, 0) + amount

    def merge(self, other: "GCounterModel") -> None:
        for replica, count in other.counts.items():
            if count > self.counts.get(replica, 0):
                self.counts[replica] = count

    def value(self) -> int:
        return sum(self.counts.values())


class ORSetModel:
    """Adds carry harness-minted addition ids; removes tombstone observed ids."""

    def __init__(self) -> None:
        self.element_of: dict[int, str] = {}
        self.known: set[int] = set()
        self.removed: set[int] = set()

    def add(self, oid: int, element: str) -> None:
        self.element_of[oid] = element
        self.known.add(oid)

    def remove(self, element: str) -> bool:
        live = {
            oid
            for oid in self.known
            if oid not in self.removed and self.element_of[oid] == element
        }
        self.removed |= live
        return bool(live)

    def merge(self, other: "ORSetModel") -> None:
        for oid in other.known - self.known:
            self.element_of[oid] = other.element_of[oid]
        self.known |= other.known
        self.removed |= other.removed

    def elements(self) -> set[str]:
        return {
            self.element_of[oid]
            for oid in self.known
            if oid not in self.removed
        }


class LWWModel:
    """Winner is the greatest (count, replica) timestamp; clock is the max seen."""

    def __init__(self) -> None:
        self.clock = 0
        self.timestamp: tuple[int, str] | None = None
        self.stored: object = None
        self.has = False

    def assign(self, replica: str, value: object) -> None:
        self.clock += 1
        self.timestamp = (self.clock, replica)
        self.stored = copy.deepcopy(value)
        self.has = True

    def merge(self, other: "LWWModel") -> None:
        if other.has and (
            not self.has
            or (other.timestamp is not None and other.timestamp > self.timestamp)
        ):
            self.timestamp = other.timestamp
            self.stored = copy.deepcopy(other.stored)
            self.has = True
        if other.clock > self.clock:
            self.clock = other.clock

    def view(self) -> tuple[bool, object]:
        return (self.has, copy.deepcopy(self.stored) if self.has else None)


class RGAModel:
    """Spec weave: siblings ordered by id descending, branches contiguous."""

    def __init__(self, replica: str) -> None:
        self.replica = replica
        self.counter = 0
        self.nodes: dict[tuple[int, str], tuple[str, tuple[int, str] | None]] = {}
        self.tombstones: set[tuple[int, str]] = set()

    def _visible_ids(self) -> list[tuple[int, str]]:
        children: dict[tuple[int, str] | None, list[tuple[int, str]]] = {}
        for node_id, (_value, predecessor) in self.nodes.items():
            children.setdefault(predecessor, []).append(node_id)
        for siblings in children.values():
            siblings.sort(reverse=True)
        ordered: list[tuple[int, str]] = []
        stack = list(reversed(children.get(None, ())))
        while stack:
            node_id = stack.pop()
            ordered.append(node_id)
            stack.extend(reversed(children.get(node_id, ())))
        return [n for n in ordered if n not in self.tombstones]

    def values(self) -> list[str]:
        return [self.nodes[n][0] for n in self._visible_ids()]

    def insert(self, index: int, value: str) -> None:
        visible = self._visible_ids()
        if index < 0 or index > len(visible):
            raise IndexError("model insert index out of range")
        predecessor = visible[index - 1] if index > 0 else None
        self.counter += 1
        self.nodes[(self.counter, self.replica)] = (value, predecessor)

    def delete(self, index: int) -> str:
        visible = self._visible_ids()
        if index < 0 or index >= len(visible):
            raise IndexError("model delete index out of range")
        node_id = visible[index]
        self.tombstones.add(node_id)
        return self.nodes[node_id][0]

    def merge(self, other: "RGAModel") -> None:
        for node_id, record in other.nodes.items():
            if node_id not in self.nodes:
                self.nodes[node_id] = record
        self.tombstones |= other.tombstones
        if other.counter > self.counter:
            self.counter = other.counter


MODEL_FACTORIES = {
    "gcounter": lambda replica: GCounterModel(),
    "orset": lambda replica: ORSetModel(),
    "lww": lambda replica: LWWModel(),
    "rga": lambda replica: RGAModel(replica),
}


# ---------------------------------------------------------------------------
# Divergence and engine plumbing.
# ---------------------------------------------------------------------------


class Divergence(Exception):
    """A mismatch between the production CRDT and the abstract model."""

    def __init__(self, where: str, detail: str) -> None:
        super().__init__(f"{where}: {detail}")
        self.where = where
        self.detail = detail
        self.events: list[dict] | None = None


class SkipOp(Exception):
    """Raised when a replayed (shrunk) operation is no longer legal."""


class Engine:
    """Holds the real replicas, their models and the pending message queue."""

    def __init__(self, crdt_type: str, replicas) -> None:
        self.type = crdt_type
        self.replicas = tuple(replicas)
        self.real = {r: REAL_CLASSES[crdt_type](r) for r in self.replicas}
        self.model = {r: MODEL_FACTORIES[crdt_type](r) for r in self.replicas}
        # msg id -> [dst, wire snapshot, model payload, remaining copies]
        self.queue: dict[int, list] = {}
        self.next_msg = 0
        self.next_oid = 0


def restore(crdt_type: str, snapshot: dict):
    """Restore a snapshot after a full JSON round trip (simulated wire)."""
    return REAL_CLASSES[crdt_type].from_snapshot(
        json.loads(json.dumps(snapshot))
    )


def public_view(crdt_type: str, real) -> object:
    if crdt_type == "gcounter":
        return real.value()
    if crdt_type == "orset":
        return sorted(real.elements())
    if crdt_type == "lww":
        return (real.has_value(), real.value() if real.has_value() else None)
    return list(real.values())


def model_view(crdt_type: str, model) -> object:
    if crdt_type == "gcounter":
        return model.value()
    if crdt_type == "orset":
        return sorted(model.elements())
    if crdt_type == "lww":
        return model.view()
    return model.values()


def canonical_form(crdt_type: str, real) -> str:
    """Canonical serialization used for cross-replica comparison.

    ``replica_id`` is always replica-local. The ORSet ``counter`` only
    describes the replica's *own* addition history (merges never adopt a
    peer's counter), so it legitimately differs between converged replicas
    and is excluded. The RGA counter and the LWW clock are Lamport-style
    maxima that do converge, so they stay in.
    """
    snap = json.loads(json.dumps(real.snapshot()))
    snap.pop("replica_id", None)
    if crdt_type == "orset":
        snap.pop("counter", None)
    return json.dumps(snap, sort_keys=True)


def check_view(ctx: Engine, replica: str, where: str) -> None:
    expected = model_view(ctx.type, ctx.model[replica])
    actual = public_view(ctx.type, ctx.real[replica])
    if expected != actual:
        raise Divergence(
            where,
            f"replica {replica!r} view diverged: "
            f"expected (model) {expected!r}, actual (crdt) {actual!r}",
        )


def apply_op(ctx: Engine, ev: dict, where: str) -> None:
    replica = ev["replica"]
    real = ctx.real[replica]
    model = ctx.model[replica]
    if ctx.type == "gcounter":
        real.increment(ev["amount"])
        model.increment(replica, ev["amount"])
    elif ctx.type == "orset":
        if ev["op"] == "add":
            real.add(ev["element"])
            model.add(ev["oid"], ev["element"])
        else:
            got = real.remove(ev["element"])
            want = model.remove(ev["element"])
            if got != want:
                raise Divergence(
                    where,
                    f"replica {replica!r} remove({ev['element']!r}) returned "
                    f"{got!r}, model expected {want!r}",
                )
    elif ctx.type == "lww":
        real.assign(copy.deepcopy(ev["value"]))
        model.assign(replica, ev["value"])
    else:  # rga
        length = len(real.values())
        if ev["op"] == "insert":
            if ev["index"] < 0 or ev["index"] > length:
                raise SkipOp
            real.insert(ev["index"], ev["value"])
            try:
                model.insert(ev["index"], ev["value"])
            except IndexError:
                raise Divergence(
                    where,
                    f"replica {replica!r} model rejected insert index "
                    f"{ev['index']} that the crdt accepted",
                )
        else:
            if ev["index"] < 0 or ev["index"] >= length:
                raise SkipOp
            got = real.delete(ev["index"])
            try:
                want = model.delete(ev["index"])
            except IndexError:
                raise Divergence(
                    where,
                    f"replica {replica!r} model rejected delete index "
                    f"{ev['index']} that the crdt accepted",
                )
            if got != want:
                raise Divergence(
                    where,
                    f"replica {replica!r} delete({ev['index']}) returned "
                    f"{got!r}, model expected {want!r}",
                )


def apply_event(ctx: Engine, events: list[dict], i: int) -> None:
    ev = events[i]
    where = f"event {i} {json.dumps(ev, sort_keys=True)}"
    kind = ev["ev"]
    if kind == "op":
        apply_op(ctx, ev, where)
        check_view(ctx, ev["replica"], where)
    elif kind == "send":
        ctx.queue[ev["msg"]] = [
            ev["dst"],
            json.loads(json.dumps(ctx.real[ev["src"]].snapshot())),
            copy.deepcopy(ctx.model[ev["src"]]),
            ev["copies"],
        ]
    else:  # deliver
        entry = ctx.queue.get(ev["msg"])
        if entry is None:
            return  # only possible in shrunk replays
        dst, wire, model_payload, _copies = entry
        ctx.real[dst].merge(restore(ctx.type, wire))
        ctx.model[dst].merge(copy.deepcopy(model_payload))
        entry[3] -= 1
        if entry[3] == 0:
            del ctx.queue[ev["msg"]]
        check_view(ctx, dst, where)


def post_phase(ctx: Engine) -> dict[str, str]:
    """Reconnect: sync to a fixed point, then run the final assertions.

    Returns the per-replica canonical forms (all identical on success).
    """
    replicas = sorted(ctx.real)
    stale = json.loads(json.dumps(ctx.real[replicas[0]].snapshot()))

    converged = False
    for _round in range(MAX_SYNC_ROUNDS):
        for src in replicas:
            wire = json.loads(json.dumps(ctx.real[src].snapshot()))
            model_payload = copy.deepcopy(ctx.model[src])
            for dst in replicas:
                if src == dst:
                    continue
                ctx.real[dst].merge(restore(ctx.type, wire))
                ctx.model[dst].merge(copy.deepcopy(model_payload))
        canonicals = {r: canonical_form(ctx.type, ctx.real[r]) for r in replicas}
        if len(set(canonicals.values())) == 1:
            converged = True
            break
    if not converged:
        detail = "; ".join(
            f"{r}: {c}" for r, c in sorted(canonicals.items())
        )
        raise Divergence(
            "post:converge",
            f"replicas did not converge after {MAX_SYNC_ROUNDS} sync "
            f"rounds: {detail}",
        )

    for replica in replicas:
        check_view(ctx, replica, "post:view")

    # Idempotence: merging the same state twice in a row changes nothing.
    for replica in replicas:
        before = canonical_form(ctx.type, ctx.real[replica])
        snap = json.loads(json.dumps(ctx.real[replica].snapshot()))
        ctx.real[replica].merge(restore(ctx.type, snap))
        ctx.real[replica].merge(restore(ctx.type, snap))
        after = canonical_form(ctx.type, ctx.real[replica])
        if after != before:
            raise Divergence(
                "post:idempotence",
                f"replica {replica!r} changed after merging the same state "
                f"twice: before {before}, after {after}",
            )

    # Stale redelivery: an old pre-reconnect snapshot must be a no-op.
    for replica in replicas:
        before = canonical_form(ctx.type, ctx.real[replica])
        ctx.real[replica].merge(restore(ctx.type, stale))
        after = canonical_form(ctx.type, ctx.real[replica])
        if after != before:
            raise Divergence(
                "post:stale-redelivery",
                f"replica {replica!r} changed after redelivering a stale "
                f"snapshot: before {before}, after {after}",
            )

    return {r: canonical_form(ctx.type, ctx.real[r]) for r in replicas}


# ---------------------------------------------------------------------------
# Scenario generation (seeded) and replay (seed-free, trace-driven).
# ---------------------------------------------------------------------------


def _gen_op(rng: random.Random, ctx: Engine, replica: str) -> dict:
    if ctx.type == "gcounter":
        return {
            "ev": "op",
            "op": "inc",
            "replica": replica,
            "amount": rng.randint(1, 5),
        }
    if ctx.type == "orset":
        visible = sorted(ctx.real[replica].elements())
        if rng.random() < 0.4:
            if visible and rng.random() < 0.75:
                element = rng.choice(visible)
            else:
                element = rng.choice(ORSET_POOL)
            return {"ev": "op", "op": "remove", "replica": replica,
                    "element": element}
        oid = ctx.next_oid
        ctx.next_oid += 1
        return {"ev": "op", "op": "add", "replica": replica,
                "element": rng.choice(ORSET_POOL), "oid": oid}
    if ctx.type == "lww":
        return {"ev": "op", "op": "assign", "replica": replica,
                "value": copy.deepcopy(rng.choice(LWW_POOL))}
    # rga
    values = ctx.real[replica].values()
    if values and rng.random() < 0.35:
        return {"ev": "op", "op": "delete", "replica": replica,
                "index": rng.randrange(len(values))}
    return {"ev": "op", "op": "insert", "replica": replica,
            "index": rng.randint(0, len(values)),
            "value": rng.choice(RGA_POOL)}


def generate_and_run(
    crdt_type: str, seed: int, n_ops: int, replicas=REPLICAS
) -> tuple[list[dict], dict[str, str]]:
    """Generate a seeded scenario, execute it with checks, return its trace.

    The trace plus the post-phase fully determine the final state, so the
    returned ``(events, canonicals)`` pair is reproducible from the seed.
    """
    rng = random.Random(
        f"model-based|{crdt_type}|{seed}|{n_ops}|{','.join(replicas)}"
    )
    ctx = Engine(crdt_type, replicas)
    events: list[dict] = []
    try:
        for _step in range(n_ops):
            roll = rng.random()
            if roll < 0.8 or not ctx.queue:
                if roll < 0.55 or not ctx.queue:
                    ev = _gen_op(rng, ctx, rng.choice(ctx.replicas))
                    events.append(ev)
                    apply_event(ctx, events, len(events) - 1)
                else:
                    src = rng.choice(ctx.replicas)
                    others = [r for r in ctx.replicas if r != src]
                    # One fan-out batch; delivery below splits it piecemeal.
                    for dst in rng.sample(others, rng.randint(1, len(others))):
                        copies = (
                            1
                            + int(rng.random() < 0.35)
                            + int(rng.random() < 0.15)
                        )
                        ev = {
                            "ev": "send",
                            "src": src,
                            "dst": dst,
                            "msg": ctx.next_msg,
                            "copies": copies,
                        }
                        ctx.next_msg += 1
                        events.append(ev)
                        apply_event(ctx, events, len(events) - 1)
            else:
                ids = sorted(ctx.queue)
                for msg in rng.sample(ids, rng.randint(1, min(3, len(ids)))):
                    ev = {"ev": "deliver", "msg": msg}
                    events.append(ev)
                    apply_event(ctx, events, len(events) - 1)
        # Reconnect: drain every delayed message, in random order.
        while ctx.queue:
            ev = {"ev": "deliver", "msg": rng.choice(sorted(ctx.queue))}
            events.append(ev)
            apply_event(ctx, events, len(events) - 1)
        canonicals = post_phase(ctx)
    except Divergence as div:
        div.events = events
        raise
    return events, canonicals


def replay_events(
    crdt_type: str, events, replicas=REPLICAS
) -> dict[str, str]:
    """Replay a recorded trace (no randomness) and run all checks.

    Operations that became illegal through trace shrinking are skipped;
    everything else must behave exactly as in the original run.
    """
    ctx = Engine(crdt_type, replicas)
    events = list(events)
    for i in range(len(events)):
        try:
            apply_event(ctx, events, i)
        except SkipOp:
            continue
    return post_phase(ctx)


# ---------------------------------------------------------------------------
# Shrinking: delta-debug the recorded trace down to a shorter failing one.
# ---------------------------------------------------------------------------


def minimize(crdt_type: str, replicas, events: list[dict]) -> list[dict]:
    """Return a 1-minimal-ish subsequence of ``events`` that still diverges."""
    attempts = [0]

    def fails(candidate: list[dict]) -> bool:
        if not candidate or attempts[0] >= SHRINK_BUDGET:
            return False
        attempts[0] += 1
        try:
            replay_events(crdt_type, candidate, replicas=replicas)
        except Divergence:
            return True
        return False

    events = list(events)
    if not fails(events):
        return events
    n = 2
    while len(events) >= 2 and attempts[0] < SHRNK_BUDGET if False else True:
        chunk = max(1, len(events) // n)
        reduced = False
        i = 0
        while i < len(events):
            candidate = events[:i] + events[i + chunk:]
            if fails(candidate):
                events = candidate
                reduced = True
                break
            i += chunk
        if attempts[0] >= SHRINK_BUDGET:
            break
        if reduced:
            n = max(2, n - 1)
        else:
            if chunk == 1:
                break
            n = min(len(events), n * 2)
    return events


# ---------------------------------------------------------------------------
# Failure reporting.
# ---------------------------------------------------------------------------


def _render_events(events: list[dict]) -> str:
    lines = ["  operation trace:"]
    for i, ev in enumerate(events):
        if ev["ev"] == "op":
            lines.append(f"    {i:4d} {json.dumps(ev, sort_keys=True)}")
    lines.append("  delivery trace:")
    for i, ev in enumerate(events):
        if ev["ev"] != "op":
            lines.append(f"    {i:4d} {json.dumps(ev, sort_keys=True)}")
    return "\n".join(lines)


def build_report(
    crdt_type: str, seed: int, n_ops: int, replicas, div: Divergence
) -> str:
    events = div.events or []
    shrunk = minimize(crdt_type, replicas, events)
    try:
        replay_events(crdt_type, shrunk, replicas=replicas)
        shrunk_outcome = "<shrunk trace did not diverge on replay>"
    except Divergence as div2:
        shrunk_outcome = f"{div2.where}: {div2.detail}"
    return "\n".join(
        [
            "model-based convergence failure",
            f"seed: {seed}",
            f"crdt type: {crdt_type}",
            f"operations requested: {n_ops}",
            f"first divergence: {div.where}: {div.detail}",
            "",
            f"original trace ({len(events)} events):",
            _render_events(events),
            "",
            f"shrunk failing trace ({len(shrunk)} events):",
            _render_events(shrunk),
            "",
            f"shrunk divergence: {shrunk_outcome}",
            "",
            "replay the shrunk trace with:",
            f"  replay_events({crdt_type!r}, "
            f"{json.dumps(shrunk, sort_keys=True)})",
        ]
    )


# ---------------------------------------------------------------------------
# Tests.
# ---------------------------------------------------------------------------


class ModelBasedScenarioTests(unittest.TestCase):
    def _run_type(self, crdt_type: str) -> None:
        for seed in range(SEEDS_PER_TYPE):
            with self.subTest(crdt=crdt_type, seed=seed):
                try:
                    generate_and_run(
                        crdt_type, seed, OPS_PER_SCENARIO if False else OPS_PER_SCENARIO, REPLICAS
                    )
                except Divergence as div:
                    self.fail(
                        build_report(
                            crdt_type, seed, OPS_PER_SCENARIO, REPLICAS, div
                        )
                    )

    def test_gcounter_scenarios(self) -> None:
        self._run_type("gcounter")

    def test_orset_scenarios(self) -> None:
        self._run_type("orset")

    def test_lww_scenarios(self) -> None:
        self._run_type("lww")

    def test_rga_scenarios(self) -> None:
        self._run_type("rga")

    def test_same_seed_reproduces_trace(self) -> None:
        for crdt_type in CRDT_TYPES:
            with self.subTest(crdt=crdt_type):
                first, _ = generate_and_run(crdt_type, 101, 40, REPLICAS)
                second, _ = generate_and_run(crdt_type, 101, 40, REPLICAS)
                self.assertEqual(first, second)

    def test_different_seeds_diverge(self) -> None:
        first, _ = generate_and_run("rga", 1, 40, REPLICAS)
        second, _ = generate_and_run("rga", 2, 40, REPLICAS)
        self.assertNotEqual(first, second)

    def test_replay_reproduces_final_state(self) -> None:
        for crdt_type in CRDT_TYPES:
            with self.subTest(crdt=crdt_type):
                events, generated = generate_and_run(crdt_type, 7, 40, REPLICAS)
                replayed = replay_events(crdt_type, events)
                self.assertEqual(generated, replayed)


if __name__ == "__main__":
    unittest.main()

